			schemaErrors: [],
			refErrors: [],
			refWarnings: [],
			orphans: [],
			completenessWarnings: [],
			traitCycles: []
		};
	}

	const response = await fetch(`${API_BASE}/api/validate`, {
		headers: getProjectHeaders()
	});
	if (!response.ok) {
		await handleResponseError(response);
	}

	return response.json();
}

/**
